    #[sqlx::test(migrations = "./migrations")]
    #[ignore = "requires DATABASE_URL and PostgreSQL CREATE DATABASE privilege"]
    async fn agent_deletion_commits_before_retrying_failed_bundle_object_cleanup(pool: PgPool) {
        let owner_id = Uuid::new_v4();
        let agent_id = Uuid::new_v4();
        let session_id = Uuid::new_v4();
        let owner_token = format!("ahs_{}", Uuid::new_v4().simple());
        let unique = Uuid::new_v4().simple().to_string();
        let object_key = format!("sessions/{session_id}/bundles/1-test.tar.zst");
        sqlx::query(
            "INSERT INTO users (id, email, password, display_name, role)
             VALUES ($1, $2, 'unused', 'Bundle cleanup owner', 'member')",
        )
        .bind(owner_id)
        .bind(format!("bundle-delete-{unique}@example.com"))
        .execute(&pool)
        .await
        .unwrap();
        sqlx::query(
            "INSERT INTO sessions (token_hash, user_id, expires_at)
             VALUES ($1, $2, now() + interval '1 hour')",
        )
        .bind(sha256_hex(&owner_token))
        .bind(owner_id)
        .execute(&pool)
        .await
        .unwrap();
        sqlx::query(
            "INSERT INTO agents (id, owner_id, name, instructions, visibility)
             VALUES ($1, $2, 'Bundle cleanup Agent', 'test', 'private')",
        )
        .bind(agent_id)
        .bind(owner_id)
        .execute(&pool)
        .await
        .unwrap();
        sqlx::query(
            "INSERT INTO hub_sessions
                 (id, owner_id, agent_id, origin_kind, lifecycle_status,
                  current_bundle_generation, current_bundle_object_key,
                  current_bundle_checksum_sha256, current_bundle_size_bytes,
                  current_bundle_history_checkpoint,
                  current_bundle_ownership_generation,
                  current_bundle_producing_engine_version,
                  current_bundle_created_at,
                  current_bundle_checkpoint_attempt_id)
             VALUES ($1, $2, $3, 'hub_native', 'offline', 1, $4,
                     $5, 12, 0, 0, '0.104.0', now(), $6)",
        )
        .bind(session_id)
        .bind(owner_id)
        .bind(agent_id)
        .bind(&object_key)
        .bind("a".repeat(64))
        .bind(Uuid::new_v4())
        .execute(&pool)
        .await
        .unwrap();

        let delete_count = Arc::new(AtomicU64::new(0));
        let app = Router::new().route(
            "/bundle-bucket/{*key}",
            axum::routing::delete({
                let delete_count = Arc::clone(&delete_count);
                move || {
                    let delete_count = Arc::clone(&delete_count);
                    async move {
                        if delete_count.fetch_add(1, Ordering::SeqCst) == 0 {
                            StatusCode::INTERNAL_SERVER_ERROR
                        } else {
                            StatusCode::NO_CONTENT
                        }
                    }
                }
            }),
        );
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let address = listener.local_addr().unwrap();
        let server = tokio::spawn(async move { axum::serve(listener, app).await.unwrap() });
        let store = crate::session_bundle_store::S3BundleStore::new(
            crate::session_bundle_store::S3BundleStoreConfig {
                endpoint: format!("http://{address}").parse().unwrap(),
                bucket: "bundle-bucket".into(),
                region: "us-test-1".into(),
                access_key_id: "test-access".into(),
                secret_access_key: "test-secret".into(),
                session_token: None,
                server_side_encryption: None,
                kms_key_id: None,
                allow_http: true,
            },
        )
        .unwrap();
        let mut state = test_state_with_browser_session_auth(pool.clone());
        state.session_bundle_store = Some(Arc::new(store));
        let state = Arc::new(state);

        let first = delete_agent(
            State(state.clone()),
            session_headers(&owner_token),
            Path(agent_id),
        )
        .await
        .unwrap_err();
        assert_eq!(first.status, StatusCode::BAD_GATEWAY);
        assert_eq!(delete_count.load(Ordering::SeqCst), 1);
        assert!(sqlx::query_scalar::<_, Option<DateTime<Utc>>>(
            "SELECT deleted_at FROM agents WHERE id = $1"
        )
        .bind(agent_id)
        .fetch_one(&pool)
        .await
        .unwrap()
        .is_some());
        assert_eq!(
            sqlx::query_as::<_, (String, Option<String>)>(
                "SELECT lifecycle_status, current_bundle_object_key
                 FROM hub_sessions WHERE id = $1"
            )
            .bind(session_id)
            .fetch_one(&pool)
            .await
            .unwrap(),
            ("historical".into(), None)
        );
        assert_eq!(
            sqlx::query_as::<_, (i64, Option<String>)>(
                "SELECT attempts, last_error
                 FROM session_bundle_deletion_queue WHERE object_key = $1"
            )
            .bind(&object_key)
            .fetch_one(&pool)
            .await
            .unwrap(),
            (1, Some("object store delete failed".into()))
        );

        assert_eq!(
            delete_agent(State(state), session_headers(&owner_token), Path(agent_id),)
                .await
                .unwrap(),
            StatusCode::NO_CONTENT
        );
        assert_eq!(delete_count.load(Ordering::SeqCst), 2);
        assert_eq!(
            sqlx::query_scalar::<_, i64>(
                "SELECT count(*) FROM session_bundle_deletion_queue WHERE object_key = $1"
            )
            .bind(&object_key)
            .fetch_one(&pool)
            .await
            .unwrap(),
            0
        );
        server.abort();
    }

