    #[sqlx::test(migrations = "./migrations")]
    async fn agent_model_configuration_copies_default_and_uses_agent_owner_scope(pool: PgPool) {
        let admin_token = create_user_session_with_role(&pool, "admin").await;
        let member_token = create_user_session_with_role(&pool, "member").await;
        let state = Arc::new(test_state_with_browser_session_auth(pool.clone()));
        let global = create_test_model_connection_for_token(
            &state,
            &admin_token,
            ModelConnectionScope::Global,
            "Agent Global",
        )
        .await;
        let owner_personal = create_test_model_connection_for_token(
            &state,
            &member_token,
            ModelConnectionScope::Personal,
            "Owner Personal",
        )
        .await;
        let admin_personal = create_test_model_connection_for_token(
            &state,
            &admin_token,
            ModelConnectionScope::Personal,
            "Admin Personal",
        )
        .await;
        let _ = set_system_default_model_selection(
            State(state.clone()),
            session_headers(&admin_token),
            Json(SetSystemDefaultModelSelectionRequest {
                selection: Some(test_model_selection(&global)),
            }),
        )
        .await
        .unwrap();

        let created = create_agent(
            State(state.clone()),
            session_headers(&member_token),
            Json(CreateAgentRequest {
                name: "Typed Model Agent".into(),
                instructions: "# Use the configured model".into(),
                visibility: "private".into(),
                public_to: Vec::new(),
                model_selection: None,
                model_settings: Some(AgentModelSettings {
                    reasoning_effort: ReasoningEffort::High,
                    ..AgentModelSettings::default()
                }),
                subagents: vec![SubagentDefinition {
                    name: "researcher".into(),
                    description: "Researches primary sources".into(),
                    developer_instructions: "# Research\n\nCite sources.".into(),
                    model_selection: None,
                    model_settings_override: AgentModelSettingsOverride {
                        reasoning_effort: ModelSettingOverride::Value(ReasoningEffort::Medium),
                        ..AgentModelSettingsOverride::default()
                    },
                    enabled: true,
                    disabled_reason: None,
                }],
                secret_declarations: Some(Vec::new()),
                tool_allowlist: default_agent_tool_allowlist(),
            }),
        )
        .await
        .unwrap()
        .0;
        assert_eq!(created.model_selection, Some(test_model_selection(&global)));
        assert_eq!(
            created.model_settings.reasoning_effort,
            ReasoningEffort::High
        );
        assert_eq!(created.subagents.len(), 1);

        let options = get_agent_model_connection_options(
            State(state.clone()),
            session_headers(&admin_token),
            Path(created.id),
        )
        .await
        .unwrap()
        .0;
        assert!(options
            .items
            .iter()
            .any(|item| item.connection_id == global.id));
        assert!(options
            .items
            .iter()
            .any(|item| item.connection_id == owner_personal.id));
        assert!(!options
            .items
            .iter()
            .any(|item| item.connection_id == admin_personal.id));

        let mut owner_scoped = update_request_from_agent(&created);
        owner_scoped.model_selection = Some(test_model_selection(&owner_personal));
        owner_scoped.model_settings.reasoning_effort = ReasoningEffort::Ultra;
        owner_scoped.subagents[0].model_selection = Some(test_model_selection(&owner_personal));
        let updated = update_agent(
            State(state.clone()),
            session_headers(&admin_token),
            Path(created.id),
            Json(owner_scoped),
        )
        .await
        .unwrap()
        .0;
        assert_eq!(
            updated.model_selection,
            Some(test_model_selection(&owner_personal))
        );
        assert_eq!(
            updated.model_settings.reasoning_effort,
            ReasoningEffort::Ultra
        );
        assert_eq!(
            updated.subagents[0].model_selection,
            Some(test_model_selection(&owner_personal))
        );

        let mut wrong_owner = update_request_from_agent(&updated);
        wrong_owner.model_selection = Some(test_model_selection(&admin_personal));
        let error = update_agent(
            State(state),
            session_headers(&admin_token),
            Path(created.id),
            Json(wrong_owner),
        )
        .await
        .unwrap_err();
        assert_eq!(error.status, StatusCode::BAD_REQUEST);
    }

    #[sqlx::test(migrations = "./migrations")]
    async fn admin_model_options_hide_super_admin_personal_connections(pool: PgPool) {
        let admin_token = create_user_session_with_role(&pool, "admin").await;
        let super_token = create_user_session_with_role(&pool, "super_admin").await;
        let state = Arc::new(test_state_with_browser_session_auth(pool));
        let super_user = require_user(&state, &session_headers(&super_token))
            .await
            .unwrap();
        let global = create_test_model_connection_for_token(
            &state,
            &admin_token,
            ModelConnectionScope::Global,
            "Super Agent Global",
        )
        .await;
        let super_personal = create_test_model_connection_for_token(
            &state,
            &super_token,
            ModelConnectionScope::Personal,
            "Super Agent Personal",
        )
        .await;
        let super_agent_id = Uuid::new_v4();
        sqlx::query(
            "INSERT INTO agents
                 (id, owner_id, name, instructions, visibility, model_policy,
                  model_connection_id, model_id)
             VALUES ($1, $2, 'Protected Model Agent', '', 'private',
                     '{\"provider\":\"hub-proxy\"}'::jsonb, $3, $4)",
        )
        .bind(super_agent_id)
        .bind(super_user.id)
        .bind(super_personal.id)
        .bind(&super_personal.allowed_model_ids[0])
        .execute(&state.pool)
        .await
        .unwrap();

        let admin_options = get_agent_model_connection_options(
            State(state.clone()),
            session_headers(&admin_token),
            Path(super_agent_id),
        )
        .await
        .unwrap()
        .0;
        assert!(admin_options
            .items
            .iter()
            .any(|item| item.connection_id == global.id));
        assert!(!admin_options
            .items
            .iter()
            .any(|item| item.connection_id == super_personal.id));

        let super_options = get_agent_model_connection_options(
            State(state.clone()),
            session_headers(&super_token),
            Path(super_agent_id),
        )
        .await
        .unwrap()
        .0;
        assert!(super_options
            .items
            .iter()
            .any(|item| item.connection_id == super_personal.id));

        let mut admin_edit = test_update_agent_request();
        admin_edit.model_selection = Some(test_model_selection(&super_personal));
        let updated = update_agent(
            State(state.clone()),
            session_headers(&admin_token),
            Path(super_agent_id),
            Json(admin_edit),
        )
        .await
        .unwrap()
        .0;
        assert_eq!(
            updated.model_selection,
            Some(test_model_selection(&super_personal))
        );

        // An ordinary admin may retain the owner's existing Personal selection,
        // but must not rebind the Agent to a different Personal connection.
        let other_super_personal = create_test_model_connection_for_token(
            &state,
            &super_token,
            ModelConnectionScope::Personal,
            "Other Super Agent Personal",
        )
        .await;
        let mut blocked = test_update_agent_request();
        blocked.model_selection = Some(test_model_selection(&other_super_personal));
        let error = update_agent(
            State(state),
            session_headers(&admin_token),
            Path(super_agent_id),
            Json(blocked),
        )
        .await
        .unwrap_err();
        assert_eq!(error.status, StatusCode::BAD_REQUEST);
    }

    #[sqlx::test(migrations = "./migrations")]
    async fn agent_creation_defaults_omitted_settings_to_the_selected_api_type(pool: PgPool) {
        let member_token = create_user_session_with_role(&pool, "member").await;
        let state = Arc::new(test_state_with_browser_session_auth(pool));

        for api_type in [
            ModelUpstreamProtocol::OpenaiChatCompletions,
            ModelUpstreamProtocol::AnthropicMessages,
        ] {
            let connection = create_model_connection(
                State(state.clone()),
                session_headers(&member_token),
                Json(CreateModelConnectionRequest {
                    vision_model_id: None,
                    scope: ModelConnectionScope::Personal,
                    name: format!("{api_type:?} Agent Connection"),
                    base_url: format!("http://127.0.0.1:1/{}", Uuid::new_v4()),
                    api_type,
                    allowed_model_ids: vec![format!("model-{}", Uuid::new_v4().simple())],
                    api_key: "test-provider-secret".into(),
                }),
            )
            .await
            .unwrap()
            .0;
            let request = serde_json::from_value::<CreateAgentRequest>(json!({
                "name": format!("{api_type:?} Agent"),
                "instructions": "Use the selected protocol.",
                "visibility": "private",
                "model_selection": test_model_selection(&connection)
            }))
            .unwrap();

            let created = create_agent(
                State(state.clone()),
                session_headers(&member_token),
                Json(request),
            )
            .await
            .unwrap()
            .0;
            assert_eq!(created.model_settings.request_settings.protocol(), api_type);
        }
    }

